/**
 * Booking availability is generated by the database. This helper mirrors its
 * weekday rotation for deterministic unit tests and preview calculations.
 * ISO weekday values are Monday=1 through Friday=5.
 */
export function createWeekdayRotation(random: () => number = Math.random): number[] {
  const days = [1, 2, 3, 4, 5];
  for (let i = days.length - 1; i > 0; i -= 1) {
    const j = Math.floor(random() * (i + 1));
    [days[i], days[j]] = [days[j], days[i]];
  }
  return days;
}

export function takeRotatingWeekdays(
  rotation: number[],
  nextIndex: number,
  random: () => number = Math.random,
): { weekdays: number[]; rotation: number[]; nextIndex: number } {
  if (rotation.length !== 5 || new Set(rotation).size !== 5 ||
      rotation.some(day => day < 1 || day > 5)) {
    rotation = createWeekdayRotation(random);
    nextIndex = 0;
  }
  const selected: number[] = [];
  let order = [...rotation];
  let cursor = Math.max(0, Math.min(nextIndex, 5));
  while (selected.length < 3) {
    if (cursor >= order.length) {
      order = createWeekdayRotation(random);
      cursor = 0;
    }
    selected.push(order[cursor]);
    cursor += 1;
  }
  return { weekdays: selected, rotation: order, nextIndex: cursor };
}

export function isTemporaryPublicRoute(pathname: string): boolean {
  return pathname === "/admin";
}

export function localDateKey(value: string | Date): string {
  const date = value instanceof Date ? value : new Date(value);
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
}

export function slotFitsDuration(slot: { starts_at: string; ends_at: string; remaining: number }, duration: number, now = Date.now()): boolean {
  return slot.remaining > 0 && new Date(slot.starts_at).getTime() > now &&
    new Date(slot.ends_at).getTime() - new Date(slot.starts_at).getTime() >= duration * 60_000;
}
